    signature = sign_message(key, message, seed=seed + index)
    return AuditProofBundle(proof, signature)


class BundleDataTest(unittest.TestCase):
    def test_field_order_and_positional_construction(self):
        self.assertEqual(
            [field.name for field in dataclasses.fields(AuditProofBundle)],
            ["proof", "signature"],
        )
        proof = AuditProof(0, 1, b"m", SigningAudit(b"a"), ())
        signature = AggregateSignature(R=5, z=7, signer_ids=(1, 3))
        bundle = AuditProofBundle(proof, signature)
        self.assertIs(bundle.proof, proof)
        self.assertIs(bundle.signature, signature)
        self.assertEqual(
            AuditProofBundle(proof=proof, signature=signature),
            bundle,
        )

    def test_frozen_value_equality_and_hash(self):
        proof = AuditProof(0, 1, b"m", SigningAudit(b"a"), ())
        signature = AggregateSignature(R=5, z=7, signer_ids=(1, 3))
        bundle = AuditProofBundle(proof, signature)
        same = AuditProofBundle(proof, signature)
        self.assertEqual(bundle, same)
        self.assertEqual(hash(bundle), hash(same))
        self.assertNotEqual(
            bundle,
            AuditProofBundle(
                proof, AggregateSignature(R=6, z=7, signer_ids=(1, 3))
            ),
        )
        with self.assertRaises(FrozenInstanceError):
            bundle.proof = proof

    def test_construction_does_not_validate(self):
        # A plain frozen value: non-proof and non-signature fields
        # construct; the codec and verifier reject them.
        AuditProofBundle("not-a-proof", "not-a-signature")
        AuditProofBundle(None, None)


class RoundTripTest(unittest.TestCase):
    def setUp(self):
        self.key = make_key()
        self.records = make_records(self.key, 9)

    def test_round_trip_for_every_size_and_index(self):
        for n in range(1, 10):
            records = self.records[:n]
            for index in range(n):
                bundle = sealed_bundle(self.key, records, index, seed=2000 + n)
                wire = encode_audit_proof_bundle(bundle)
                decoded = decode_audit_proof_bundle(wire)
                self.assertEqual(decoded, bundle, msg=f"n={n} index={index}")
